 void styleSeek(){android.graphics.drawable.GradientDrawable track=new android.graphics.drawable.GradientDrawable();track.setColor(PlayerTheme.TRACK);track.setCornerRadius(dp(2));android.graphics.drawable.GradientDrawable buffer=new android.graphics.drawable.GradientDrawable();buffer.setColor(PlayerTheme.TRACK_BUFFER);buffer.setCornerRadius(dp(2));android.graphics.drawable.GradientDrawable played=new android.graphics.drawable.GradientDrawable();played.setColor(PlayerTheme.TRACK_PLAYED);played.setCornerRadius(dp(2));android.graphics.drawable.LayerDrawable layers=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{track,new android.graphics.drawable.ClipDrawable(buffer,Gravity.LEFT,1),new android.graphics.drawable.ClipDrawable(played,Gravity.LEFT,1)});int[] ids={android.R.id.background,android.R.id.secondaryProgress,android.R.id.progress};for(int n=0;n<3;n++){layers.setId(n,ids[n]);layers.setLayerHeight(n,dp(3));layers.setLayerGravity(n,Gravity.CENTER_VERTICAL);}seek.setProgressDrawable(layers);android.graphics.drawable.GradientDrawable thumb=new android.graphics.drawable.GradientDrawable();thumb.setShape(1);thumb.setColor(PlayerTheme.ACCENT);thumb.setSize(dp(12),dp(12));seek.setThumb(thumb);seek.setSplitTrack(false);}
