 void subtitles(){List<CinemaMenu.Item> rows=new ArrayList<>();rows.add(CinemaMenu.item("内嵌字幕 / 关闭",()->tracks(C.TRACK_TYPE_TEXT)));rows.add(CinemaMenu.item("搜索在线字幕",()->OnlineSubtitleController.open(a)));JSONArray subs=a.source.optJSONArray("subtitles");for(int i=0;subs!=null&&i<subs.length();i++){JSONObject s=subs.optJSONObject(i);if(s==null||s.optString("url").isEmpty())continue;final String url=s.optString("url"),name=s.optString("lang",s.optString("name","片源字幕"));rows.add(CinemaMenu.item(name,()->a.loadSubtitleFile(url,name)));}CinemaMenu.show(a,"字幕",rows);}
